"""Hoeffding Tree (VFDT) implementation for incremental stream learning."""

from __future__ import annotations

from dataclasses import dataclass
import math
from typing import Dict, Iterable, List, Optional, Tuple

from attribute_observers import NumericAttributeObserver
from classifiers import AbstractClassifier, compute_hoeffding_bound
from streams import Instance


@dataclass
class SplitSuggestion:
    """Candidate split proposed by an attribute observer."""

    merit: float
    attribute_index: int
    split_value: float
    post_split_distributions: List[List[float]]


class HoeffdingTreeNode:
    """Base node type for Hoeffding Trees."""

    def __init__(self, depth: int = 0):
        self.depth = depth

    def is_leaf(self) -> bool:
        raise NotImplementedError


class HoeffdingTreeLeaf(HoeffdingTreeNode):
    """Learning leaf that stores class and attribute statistics."""

    def __init__(
        self,
        depth: int = 0,
        num_attributes: Optional[int] = None,
        class_distribution: Optional[Dict[int, float]] = None,
    ):
        super().__init__(depth=depth)
        self.num_attributes = num_attributes
        self.class_distribution: Dict[int, float] = dict(class_distribution or {})
        self.attribute_observers: List[NumericAttributeObserver] = []
        self.weight_seen = float(sum(self.class_distribution.values()))
        self.last_split_attempt_at = self.weight_seen

    def is_leaf(self) -> bool:
        return True

    def _ensure_observers(self, num_attributes: int):
        if self.num_attributes is None:
            self.num_attributes = num_attributes
        if not self.attribute_observers:
            self.attribute_observers = [
                NumericAttributeObserver() for _ in range(self.num_attributes)
            ]

    def learn_from_instance(self, instance: Instance):
        self._ensure_observers(instance.num_attributes)
        self.class_distribution[instance.label] = (
            self.class_distribution.get(instance.label, 0.0) + 1.0
        )
        self.weight_seen += 1.0
        for index, value in enumerate(instance.features):
            self.attribute_observers[index].observe(value, instance.label)

    def get_class_votes(self) -> Dict[int, float]:
        return dict(self.class_distribution)

    def majority_class(self, default: int = 0) -> int:
        if not self.class_distribution:
            return default
        return max(
            sorted(self.class_distribution.items()),
            key=lambda item: (item[1], -item[0]),
        )[0]

    def is_pure(self) -> bool:
        active_classes = [count for count in self.class_distribution.values() if count > 0.0]
        return len(active_classes) <= 1

    def get_best_split_suggestions(self, num_classes: int) -> List[SplitSuggestion]:
        suggestions: List[SplitSuggestion] = []
        for index, observer in enumerate(self.attribute_observers):
            merit, split_value, post_split_distributions = observer.get_best_split_suggestion(
                num_classes
            )
            if post_split_distributions and merit > 0.0:
                suggestions.append(
                    SplitSuggestion(
                        merit=merit,
                        attribute_index=index,
                        split_value=split_value,
                        post_split_distributions=post_split_distributions,
                    )
                )
        suggestions.sort(key=lambda suggestion: (suggestion.merit, -suggestion.attribute_index))
        return suggestions


class HoeffdingTreeSplit(HoeffdingTreeNode):
    """Binary numeric split node."""

    def __init__(
        self,
        split_attribute: int,
        split_value: float,
        left_child: HoeffdingTreeNode,
        right_child: HoeffdingTreeNode,
        depth: int = 0,
        class_distribution: Optional[Dict[int, float]] = None,
    ):
        super().__init__(depth=depth)
        self.split_attribute = split_attribute
        self.split_value = split_value
        self.left_child = left_child
        self.right_child = right_child
        self.class_distribution: Dict[int, float] = dict(class_distribution or {})

    def is_leaf(self) -> bool:
        return False

    def branch_for_instance(self, instance: Instance) -> str:
        if instance.features[self.split_attribute] < self.split_value:
            return "left"
        return "right"

    def get_child(self, branch: str) -> HoeffdingTreeNode:
        return self.left_child if branch == "left" else self.right_child

    def set_child(self, branch: str, child: HoeffdingTreeNode):
        if branch == "left":
            self.left_child = child
        else:
            self.right_child = child

    def iter_children(self) -> Iterable[HoeffdingTreeNode]:
        yield self.left_child
        yield self.right_child


class HoeffdingTree(AbstractClassifier):
    """Incremental decision tree learner based on the Hoeffding bound."""

    def __init__(
        self,
        grace_period: int = 200,
        split_confidence: float = 1e-7,
        tie_threshold: float = 0.05,
        max_depth: int = 20,
        num_classes: Optional[int] = None,
    ):
        super().__init__()
        self.grace_period = grace_period
        self.split_confidence = split_confidence
        self.tie_threshold = tie_threshold
        self.max_depth = max_depth
        self.num_classes = num_classes or 0
        self.root: HoeffdingTreeNode = HoeffdingTreeLeaf(depth=0)
        self.global_class_distribution: Dict[int, float] = {}

    def _update_global_distribution(self, label: int):
        self.global_class_distribution[label] = (
            self.global_class_distribution.get(label, 0.0) + 1.0
        )

    def _route_to_leaf(
        self, instance: Instance
    ) -> Tuple[HoeffdingTreeLeaf, Optional[HoeffdingTreeSplit], Optional[str], List[HoeffdingTreeSplit]]:
        node = self.root
        parent: Optional[HoeffdingTreeSplit] = None
        branch: Optional[str] = None
        path: List[HoeffdingTreeSplit] = []
        while not node.is_leaf():
            split = node  # type: ignore[assignment]
            assert isinstance(split, HoeffdingTreeSplit)
            path.append(split)
            parent = split
            branch = split.branch_for_instance(instance)
            node = split.get_child(branch)
        return node, parent, branch, path  # type: ignore[return-value]

    def train(self, instance: Instance):
        self.instances_seen += 1
        self.num_classes = max(self.num_classes, instance.label + 1)
        self._update_global_distribution(instance.label)

        leaf, parent, branch, _ = self._route_to_leaf(instance)
        leaf.learn_from_instance(instance)

        should_check_split = (
            leaf.depth < self.max_depth
            and not leaf.is_pure()
            and leaf.weight_seen - leaf.last_split_attempt_at >= self.grace_period
        )
        if should_check_split:
            self._attempt_split(leaf, parent, branch)

    def _attempt_split(
        self,
        leaf: HoeffdingTreeLeaf,
        parent: Optional[HoeffdingTreeSplit],
        branch: Optional[str],
    ):
        leaf.last_split_attempt_at = leaf.weight_seen
        suggestions = leaf.get_best_split_suggestions(max(2, self.num_classes))
        if not suggestions:
            return

        best = suggestions[-1]
        second_best_merit = suggestions[-2].merit if len(suggestions) > 1 else 0.0
        range_val = math.log2(max(2, self.num_classes))
        epsilon = compute_hoeffding_bound(
            range_val=range_val,
            confidence=self.split_confidence,
            n=int(max(1, leaf.weight_seen)),
        )

        if best.merit - second_best_merit <= epsilon and epsilon >= self.tie_threshold:
            return

        left_distribution = self._distribution_from_list(best.post_split_distributions[0])
        right_distribution = self._distribution_from_list(best.post_split_distributions[1])
        left_child = HoeffdingTreeLeaf(
            depth=leaf.depth + 1,
            num_attributes=leaf.num_attributes,
            class_distribution=left_distribution,
        )
        right_child = HoeffdingTreeLeaf(
            depth=leaf.depth + 1,
            num_attributes=leaf.num_attributes,
            class_distribution=right_distribution,
        )
        split = HoeffdingTreeSplit(
            split_attribute=best.attribute_index,
            split_value=best.split_value,
            left_child=left_child,
            right_child=right_child,
            depth=leaf.depth,
            class_distribution=leaf.get_class_votes(),
        )
        if parent is None:
            self.root = split
        else:
            assert branch is not None
            parent.set_child(branch, split)

    @staticmethod
    def _distribution_from_list(distribution: List[float]) -> Dict[int, float]:
        return {index: value for index, value in enumerate(distribution) if value > 0.0}

    def get_votes(self, instance: Instance) -> Dict[int, float]:
        leaf, _, _, _ = self._route_to_leaf(instance)
        votes = leaf.get_class_votes()
        if votes:
            return votes
        return dict(self.global_class_distribution)

    def predict(self, instance: Instance) -> int:
        votes = self.get_votes(instance)
        if not votes:
            return 0
        return max(sorted(votes.items()), key=lambda item: (item[1], -item[0]))[0]

    def get_tree_size(self) -> Dict[str, int]:
        num_leaves = 0
        num_splits = 0
        stack = [self.root]
        while stack:
            node = stack.pop()
            if node.is_leaf():
                num_leaves += 1
                continue
            num_splits += 1
            assert isinstance(node, HoeffdingTreeSplit)
            stack.extend(node.iter_children())
        return {
            "num_leaves": num_leaves,
            "num_splits": num_splits,
            "total_nodes": num_leaves + num_splits,
        }

