"""SAM-KNN implementation with short-term and long-term memories."""

from __future__ import annotations

import heapq
import math
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

from classifiers import AbstractClassifier


FeatureVector = Sequence[float]


def _euclidean_distance(
    left: FeatureVector,
    right: FeatureVector,
    feature_weights: Optional[Sequence[float]] = None,
) -> float:
    total = 0.0
    if feature_weights is None:
        for left_value, right_value in zip(left, right):
            delta = left_value - right_value
            total += delta * delta
    else:
        for left_value, right_value, weight in zip(left, right, feature_weights):
            delta = left_value - right_value
            total += weight * delta * delta
    return math.sqrt(total)


def _knn_predict(
    query: FeatureVector,
    features: Sequence[FeatureVector],
    labels: Sequence[int],
    k: int,
    feature_weights: Optional[Sequence[float]] = None,
    exclude_index: Optional[int] = None,
) -> int:
    if not features:
        return 0

    distances = []
    for index, (candidate, label) in enumerate(zip(features, labels)):
        if exclude_index is not None and index == exclude_index:
            continue
        distance = _euclidean_distance(query, candidate, feature_weights)
        distances.append((distance, label))
    if not distances:
        return labels[exclude_index] if exclude_index is not None and exclude_index < len(labels) else 0

    neighbors = heapq.nsmallest(min(k, len(distances)), distances, key=lambda item: item[0])
    votes: Dict[int, int] = {}
    distance_sums: Dict[int, float] = {}
    for distance, label in neighbors:
        votes[label] = votes.get(label, 0) + 1
        distance_sums[label] = distance_sums.get(label, 0.0) + distance

    return max(
        votes.keys(),
        key=lambda label: (votes[label], -distance_sums[label], -label),
    )


def _copy_features(features: FeatureVector) -> List[float]:
    return [float(value) for value in features]


class ShortTermMemory:
    """Fixed-size FIFO memory for recent instances."""

    def __init__(
        self,
        max_size: int = 5000,
        feature_weights: Optional[Sequence[float]] = None,
    ):
        self.max_size = max_size
        self.feature_weights = feature_weights
        self.features: List[List[float]] = []
        self.labels: List[int] = []

    def add(self, features: FeatureVector, label: int) -> Optional[Tuple[List[float], int]]:
        evicted = None
        if len(self.features) >= self.max_size:
            evicted = (self.features.pop(0), self.labels.pop(0))
        self.features.append(_copy_features(features))
        self.labels.append(int(label))
        return evicted

    def knn_predict(self, query: FeatureVector, k: int) -> int:
        return _knn_predict(
            query=query,
            features=self.features,
            labels=self.labels,
            k=k,
            feature_weights=self.feature_weights,
        )

    def get_size(self) -> int:
        return len(self.features)

    def get_window(self) -> Tuple[List[List[float]], List[int]]:
        return ([feature[:] for feature in self.features], list(self.labels))


class LongTermMemory:
    """Compressed memory that keeps longer-lived concept information."""

    def __init__(
        self,
        max_size: int = 10000,
        min_cluster_size: int = 10,
        feature_weights: Optional[Sequence[float]] = None,
    ):
        self.max_size = max_size
        self.min_cluster_size = min_cluster_size
        self.feature_weights = feature_weights
        self.features: List[List[float]] = []
        self.labels: List[int] = []

    def add(self, features: FeatureVector, label: int):
        self.features.append(_copy_features(features))
        self.labels.append(int(label))

    def clean(
        self,
        stm_features: Sequence[FeatureVector],
        stm_labels: Sequence[int],
        k: int = 5,
    ):
        if not stm_features:
            return

        retained_features: List[List[float]] = []
        retained_labels: List[int] = []
        for features, label in zip(self.features, self.labels):
            prediction = _knn_predict(
                query=features,
                features=stm_features,
                labels=stm_labels,
                k=k,
                feature_weights=self.feature_weights,
            )
            if prediction == label:
                retained_features.append(features)
                retained_labels.append(label)

        self.features = retained_features
        self.labels = retained_labels

    def compress(self):
        if len(self.features) <= self.max_size:
            return

        class_to_points: Dict[int, List[List[float]]] = {}
        for features, label in zip(self.features, self.labels):
            class_to_points.setdefault(label, []).append(features)

        compressed_features: List[List[float]] = []
        compressed_labels: List[int] = []
        total_points = max(1, len(self.features))

        for label, points in sorted(class_to_points.items()):
            if len(points) <= self.min_cluster_size:
                compressed_features.extend(points)
                compressed_labels.extend([label] * len(points))
                continue

            target_size = max(1, round(len(points) * self.max_size / total_points))
            target_size = min(target_size, len(points))
            if target_size >= len(points):
                compressed_features.extend(points)
                compressed_labels.extend([label] * len(points))
                continue

            centroids = self._kmeans(points, target_size)
            compressed_features.extend(centroids)
            compressed_labels.extend([label] * len(centroids))

        self.features = compressed_features[: self.max_size]
        self.labels = compressed_labels[: self.max_size]

    def _kmeans(self, points: Sequence[FeatureVector], k: int) -> List[List[float]]:
        centroids = [
            _copy_features(points[index * len(points) // k]) for index in range(k)
        ]
        for _ in range(5):
            clusters: List[List[FeatureVector]] = [[] for _ in range(k)]
            for point in points:
                best_index = min(
                    range(k),
                    key=lambda index: _euclidean_distance(
                        point,
                        centroids[index],
                        self.feature_weights,
                    ),
                )
                clusters[best_index].append(point)

            new_centroids: List[List[float]] = []
            for index, cluster in enumerate(clusters):
                if not cluster:
                    new_centroids.append(centroids[index])
                    continue
                dimensions = len(cluster[0])
                centroid = []
                for dimension in range(dimensions):
                    centroid.append(
                        sum(point[dimension] for point in cluster) / len(cluster)
                    )
                new_centroids.append(centroid)

            if new_centroids == centroids:
                break
            centroids = new_centroids
        return centroids

    def knn_predict(self, query: FeatureVector, k: int) -> int:
        return _knn_predict(
            query=query,
            features=self.features,
            labels=self.labels,
            k=k,
            feature_weights=self.feature_weights,
        )

    def get_size(self) -> int:
        return len(self.features)


class SAMModel(AbstractClassifier):
    """Self-adjusting-memory kNN classifier for drifting streams."""

    def __init__(
        self,
        k: int = 5,
        stm_max_size: int = 5000,
        ltm_max_size: int = 10000,
        min_stm_size: int = 50,
        ltm_clean_frequency: int = 500,
        feature_weights: Optional[Sequence[float]] = None,
    ):
        super().__init__()
        self.k = k
        self.min_stm_size = min_stm_size
        self.ltm_clean_frequency = ltm_clean_frequency
        self.feature_weights = feature_weights
        self.stm = ShortTermMemory(max_size=stm_max_size, feature_weights=feature_weights)
        self.ltm = LongTermMemory(max_size=ltm_max_size, feature_weights=feature_weights)
        self.prediction_count = 0
        self.stm_preferred_count = 0
        self._cached_memory_scores: Optional[Tuple[float, float]] = None
        self._cached_prediction_count = 0
        self._accuracy_refresh_interval = 25
        self._validation_window_size = 20

    def partial_fit(self, features: FeatureVector, label: int):
        self.instances_seen += 1
        evicted = self.stm.add(features, label)
        if evicted is not None:
            old_features, old_label = evicted
            self.ltm.add(old_features, old_label)

        if (
            self.instances_seen % self.ltm_clean_frequency == 0
            and self.ltm.get_size() > 0
            and self.stm.get_size() >= self.min_stm_size
        ):
            stm_features, stm_labels = self.stm.get_window()
            self.ltm.clean(stm_features, stm_labels, k=self.k)
            self.ltm.compress()

        self._cached_memory_scores = None

    def train(self, instance):
        if hasattr(instance, "features") and hasattr(instance, "label"):
            self.partial_fit(instance.features, instance.label)
            return
        raise TypeError("SAMModel.train expects a stream Instance with features and label")

    def _normalize_query(self, features) -> List[float]:
        if hasattr(features, "features"):
            features = features.features
        return _copy_features(features)

    def predict(self, features) -> int:
        query = self._normalize_query(features)
        stm_prediction, stm_accuracy, ltm_prediction, ltm_accuracy = self._evaluate_memories(
            query,
            self.k,
        )

        use_stm = (
            self.ltm.get_size() == 0
            or self.stm.get_size() < self.min_stm_size
            or stm_accuracy >= ltm_accuracy
        )
        prediction = stm_prediction if use_stm else ltm_prediction
        self.prediction_count += 1
        if use_stm:
            self.stm_preferred_count += 1
        return prediction

    def get_votes(self, instance) -> Dict[int, float]:
        prediction = self.predict(instance)
        return {prediction: 1.0}

    def _evaluate_memories(
        self,
        query: FeatureVector,
        k: int,
    ) -> Tuple[int, float, int, float]:
        stm_prediction = self.stm.knn_predict(query, k) if self.stm.get_size() > 0 else 0
        ltm_prediction = (
            self.ltm.knn_predict(query, k) if self.ltm.get_size() > 0 else stm_prediction
        )

        if (
            self._cached_memory_scores is None
            or self.prediction_count - self._cached_prediction_count
            >= self._accuracy_refresh_interval
        ):
            stm_accuracy, ltm_accuracy = self._refresh_memory_scores(k)
            self._cached_memory_scores = (stm_accuracy, ltm_accuracy)
            self._cached_prediction_count = self.prediction_count
        else:
            stm_accuracy, ltm_accuracy = self._cached_memory_scores

        return stm_prediction, stm_accuracy, ltm_prediction, ltm_accuracy

    def _refresh_memory_scores(self, k: int) -> Tuple[float, float]:
        stm_features, stm_labels = self.stm.get_window()
        if not stm_features:
            return 0.0, 0.0

        validation_size = min(self._validation_window_size, len(stm_features))
        start_index = len(stm_features) - validation_size
        stm_correct = 0
        ltm_correct = 0

        for index in range(start_index, len(stm_features)):
            query = stm_features[index]
            actual = stm_labels[index]

            stm_prediction = _knn_predict(
                query=query,
                features=stm_features,
                labels=stm_labels,
                k=k,
                feature_weights=self.feature_weights,
                exclude_index=index,
            )
            stm_correct += int(stm_prediction == actual)

            if self.ltm.get_size() > 0:
                ltm_prediction = self.ltm.knn_predict(query, k)
                ltm_correct += int(ltm_prediction == actual)

        stm_accuracy = stm_correct / validation_size
        if self.ltm.get_size() == 0:
            return stm_accuracy, 0.0
        return stm_accuracy, ltm_correct / validation_size

    def get_memory_sizes(self) -> Dict[str, int]:
        return {"stm": self.stm.get_size(), "ltm": self.ltm.get_size()}
